#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
const ll MOD = 998244353;

ll pw(ll a,ll e){ ll r=1; while(e){ if(e&1) r=r*a%MOD; a=a*a%MOD; e>>=1;} return r; }

struct Random{
  ull X;
  void init(ull seed){X=seed;}
  ull Rand(){ X^=X<<13; X^=X>>7; X^=X<<17; return X; }
};

int main(){
  ll n,q; ull seed1,seed2; ll A,B;
  if(scanf("%lld %lld %llu %llu %lld %lld",&n,&q,&seed1,&seed2,&A,&B)!=6) return 0;
  A%=MOD; B%=MOD;
  Random R; R.init(seed1);
  vector<unsigned char> seq(n+1);
  for(int i=1;i<=n;i++) seq[i]=R.Rand()&1;
  vector<int> inv(n+1);
  if(n>=1) inv[1]=1;
  for(int i=2;i<=n;i++) inv[i]=(ll)(MOD - MOD/i)*inv[MOD%i]%MOD;
  ll inv2=(MOD+1)/2, inv6=pw(6,MOD-2);
  vector<int> f2(n+1);
  for(int m=0;m<=n;m++){
    f2[m]=(ll)m*(m+1)%MOD*(2*m+1)%MOD*inv6%MOD;
  }
  vector<int> Wgt(n+1);
  ll Ssum=0;
  for(int i=1;i<=n;i++){
    ll p2=(f2[i-1]+f2[n-i])%MOD;
    ll t1=(ll)(i-1)*i/2;
    ll t2b=(ll)(n-i)*(n-i+1)/2;
    ll p1=(t1+t2b)%MOD;
    ll w=(A*p2%MOD + B*p1%MOD)%MOD;
    Wgt[i]=w;
    Ssum=(Ssum+w)%MOD;
  }
  int k=0; ll Gsum=0;
  for(int i=1;i<=n;i++) if(seq[i]){ k++; Gsum=(Gsum+Wgt[i])%MOD; }
  ll invn=inv[n];
  vector<int> d(n+1,0);
  {
    ll pinv=inv[n-2];
    ll pa=1,pb=0,ca=(ll)(n%MOD)*pinv%MOD,cb=pinv;
    for(int kk=2;kk<=n-2;kk++){
      ll na=((ll)(n%MOD)*ca%MOD - (ll)(kk-1)*pa%MOD + MOD)%MOD*inv[n-kk-1]%MOD;
      ll nb=((ll)(n%MOD)*cb%MOD - (ll)(kk-1)*pb%MOD + MOD)%MOD*inv[n-kk-1]%MOD;
      pa=ca;pb=cb;ca=na;cb=nb;
    }
    ll denom=(ca+1)%MOD;
    ll t=(MOD-cb)%MOD*pw(denom,MOD-2)%MOD;
    d[1]=t;
    d[2]=(ll)(n%MOD)*t%MOD;
    d[2]=(d[2]+1)%MOD*pinv%MOD;
    for(int kk=2;kk<=n-2;kk++){
      d[kk+1]=((ll)(n%MOD)*d[kk]%MOD - (ll)(kk-1)*d[kk-1]%MOD + MOD)%MOD*inv[n-kk-1]%MOD;
    }
  }
  vector<int> eR(n+1,0);
  {
    ll ha=1,hb=0,A_=0,B_=0;
    for(int kk=1;kk<=n;kk++){
      A_=(A_+ha)%MOD; B_=(B_+hb)%MOD;
      if(kk<n){
        ll na=((ll)kk*ha%MOD - n%MOD + MOD)%MOD*inv[n-kk]%MOD;
        ll nb=((ll)kk*hb%MOD - n%MOD + MOD)%MOD*inv[n-kk]%MOD;
        ha=na;hb=nb;
      }
    }
    ll t2=(MOD-B_)%MOD*pw(A_,MOD-2)%MOD;
    ll hha=1,hhb=0; ll cur=0;
    for(int kk=1;kk<=n-1;kk++){
      ll hv=(hha*t2+hhb)%MOD;
      cur=(cur+hv)%MOD;
      eR[kk]=(cur-1+MOD)%MOD;
      if(kk<n){
        ll na=((ll)kk*hha%MOD - n%MOD + MOD)%MOD*inv[n-kk]%MOD;
        ll nb=((ll)kk*hhb%MOD - n%MOD + MOD)%MOD*inv[n-kk]%MOD;
        hha=na;hhb=nb;
      }
    }
  }
  Random R2; R2.init(seed2);
  ll ans=0;
  ll Gbar=Ssum*invn%MOD;
  for(ll ii=0; ii<q; ii++){
    int idx=(int)(R2.Rand()%n+1);
    int p=(int)(R2.Rand()%n+1);
    if(seq[idx]==0){ seq[idx]=1; k++; Gsum=(Gsum+Wgt[idx])%MOD; }
    else { seq[idx]=0; k--; Gsum=(Gsum-Wgt[idx]+MOD)%MOD; }
    ll res;
    if(k==0||k==n) res=0;
    else {
      ll G1=Gsum*invn%MOD;
      ll y=((eR[k] - (ll)k*d[k])%MOD+MOD)%MOD*invn%MOD;
      ll gp=(ll)Wgt[p]*invn%MOD;
      res=(gp + y*Gbar%MOD + (ll)d[k]*G1%MOD)%MOD;
    }
    ans ^= res;
  }
  printf("%lld\n",ans);
  return 0;
}

