#include <bits/stdc++.h>
using namespace std;
int N; double A,B;
vector<double> solveD(){ // returns d[1..N-1]
  vector<double> d(N+1,0);
  if(N==3){ d[1]=-0.25; d[2]=0.25; return d; }
  // linear in t
  double pa=1,pb=0, ca=(double)N/(N-2), cb=1.0/(N-2);
  for(int k=2;k<=N-2;k++){
    double na=((double)N*ca-(k-1)*pa)/(N-k-1);
    double nb=((double)N*cb-(k-1)*pb)/(N-k-1);
    pa=ca;pb=cb;ca=na;cb=nb;
  }
  double t=-cb/(ca+1.0);
  d[1]=t; d[2]=((double)N*t+1)/(N-2);
  for(int k=2;k<=N-2;k++) d[k+1]=((double)N*d[k]-(k-1)*d[k-1])/(N-k-1);
  return d;
}
vector<double> solveE(){ // e[1..N-1]
  vector<double> e(N+1,0);
  double ha=1,hb=0,A_=0,B_=0;
  for(int k=1;k<=N;k++){ A_+=ha;B_+=hb; if(k<N){ double na=(k*ha)/(N-k); double nb=(k*hb-N)/(N-k); ha=na;hb=nb; } }
  double t=-B_/A_;
  ha=1;hb=0; double cur=0;
  for(int k=1;k<=N-1;k++){ cur+=ha*t+hb; e[k]=cur; if(k<N){ double na=(k*ha)/(N-k); double nb=(k*hb-N)/(N-k); ha=na;hb=nb; } }
